const images = items
  .filter(item => item.json.mimeType?.startsWith('image/'))
  .sort((a, b) => new Date(a.json.createdTime || 0) - new Date(b.json.createdTime || 0))
  .map((item, index) => ({
    index: index + 1,
    id: item.json.id,
    name: item.json.name,
    mimeType: item.json.mimeType,
    webViewLink: item.json.webViewLink || '',
    thumbnailLink: item.json.thumbnailLink || ''
  }));

if (!images.length) {
  throw new Error('No hay imágenes en la carpeta configurada de Google Drive.');
}

return [{
  json: {
    photoCount: images.length,
    photos: images,
    photoSummary: images.map(i => `${i.index}. ${i.name}`).join('\n')
  }
}];

